            "content": "(1) (الذكاء الاصطناعي القابل للتفسير - Explainable AI - XAI)... أساليب تساعد البشر على فهم العوامل التي أسهمت في وصول النظام إلى مخرج أو قرار معين. وعندما تكون آلية الوصول إلى النتيجة غير واضحة، يصعب تقييمها واكتشاف الأخطاء أو التحيز.\n\n(2) (المسؤولية - Responsibility)... تحديد أدوار وواجبات الأطراف المرتبطة بتطوير النظام وتشغيله واستخدامه، مثل المطور والجهة المشغّلة والمستخدم. ولا يوجد توزيع واحد للمسؤولية يصلح لكل السياقات؛ إذ يختلف باختلاف النظام والاستخدام والقواعد المعمول بها.\n\n(3) (المساءلة - Accountability)... تحديد الجهات المسؤولة عن النظام وقراراته وآثاره، وإمكان محاسبتها وفق أدوارها. ملاحظة: المساءلة ليست القدرة على شرح القرار — تلك وظيفة الذكاء الاصطناعي القابل للتفسير (XAI) — بل تحديد من يُحاسب على النتيجة.\n\n(4) (الشفافية - Transparency)... إتاحة معلومات واضحة ومناسبة عن النظام واستخدامه وعملية اتخاذ القرار وحدوده."
