            "content": "(1) (HTTPS)... بروتوكول اتصال يشفّر البيانات المنقولة عبر الويب ويحميها من التنصت والتلاعب بها أثناء النقل. وتعتمد اتصالات HTTPS في الويب الحديث عادةً على بروتوكول TLS (أمان طبقة النقل - Transport Layer Security) لتأمين الاتصال، حيث يوفر TLS سرية البيانات وسلامتها أثناء النقل، ويساعد المتصفح على التحقق من هوية الخادم واسم النطاق.\n\n(2) كيف يؤمّن TLS الاتصال:\n① يطلب المتصفح الشهادة الرقمية للخادم ويتحقق من صحتها.\n② عند بدء الاتصال، تُستخدم تقنيات المفتاح العام للمساعدة في إنشاء أو اشتقاق مفاتيح جلسة مشتركة بأمان.\n③ بعد إنشاء مفتاح الجلسة، تُشفّر البيانات المتبادلة بين المتصفح والخادم باستخدام التشفير بالمفتاح المتناظر، مما يجمع بين أمان تبادل المفاتيح وسرعة التشفير أثناء نقل البيانات.",
