            "correctAnswer": "الإجابة النموذجية: \n1) دورة PDCA:\n- الهدف: القياس والتحسين المستمر لجودة وكفاءة العمليات والأنظمة.\n- زاوية الانطلاق: الأهداف ومؤشرات الأداء المقاسة (Metrics-driven).\n- المراحل: خطّط (Plan)، نفّذ (Do)، تحقّق (Check)، تصرّف (Act).\n2) التفكير التصميمي (Design Thinking):\n- الهدف: حل المشكلات المعقدة وتوليد حلول مبتكرة للمستخدمين.\n- زاوية الانطلاق: التعاطف الإنساني وفهم احتياجات المستخدم وسياقه (User-centered).\n- المراحل: التعاطف (Empathize)، التعريف (Define)، توليد الأفكار (Ideate)، النموذج الأولي (Prototype)، الاختبار (Test).\n3) تكامل اختبار A/B معهما:\n- يُستخدم اختبار A/B كأداة علمية حاسمة في مرحلة 'الاختبار (Test)' بالتفكير التصميمي لمقارنة النموذج الأولي مع القديم، وفي مرحلتي 'نفّذ وتحقّق (Do & Check)' بدورة PDCA لقياس أثر التعديل بالبيانات الرقمية المجردة قبل اعتماده النهائي في مرحلة (Act).",
